-- Replace the starter catalog with the ZHI-MART 2026 price list (85% discount).
-- Source: ZHI-MART_Price_List_85_Discount_2026_.docx — 130 products + 5 fixed-rate gift boxes.
-- Offer prices are taken exactly as printed in the list; categories follow the list's section
-- order; images are the closest existing category image; initial stock is 100 per product
-- (set real counts in Admin → Inventory).
--
-- Old products: deleted when no order references them, otherwise archived (hidden from the
-- storefront, kept for order history). Their stock ledger rows go with them on delete.

UPDATE products SET is_active = FALSE, version = version + 1, updated_at = now()
WHERE id NOT LIKE 'zm26-%' AND is_active
  AND EXISTS (SELECT 1 FROM order_items oi WHERE oi.product_id = products.id);

DELETE FROM products p
WHERE p.id NOT LIKE 'zm26-%'
  AND NOT EXISTS (SELECT 1 FROM order_items oi WHERE oi.product_id = p.id);

