inserted AS (
  INSERT INTO products (id, name, category, brand, pack_info, pieces_per_pack, price_paise,
                        original_price_paise, image_url, description, stock, sort_order)
  SELECT id, name, category, brand, pack_info, pieces_per_pack, price_paise, original_price_paise,
         image_url, description, stock, sort_order
  FROM incoming
  ON CONFLICT (id) DO NOTHING
  RETURNING id, stock
)
INSERT INTO stock_movements (product_id, delta, stock_after, reason, note)
SELECT id, stock, stock, 'initial', '2026 price list import'
FROM inserted
WHERE stock > 0;
